function put16(a, off, v) {
  a[off] = v & 255;
  a[off + 1] = (v >> 8) & 255;
}
function mirrorFF() { return Array(55).fill(255); }
function mirrorZero() { return Array(55).fill(0); }
function mirrorOpen() {
  const m = mirrorZero();
  m[1] = 1;
  put16(m, 0x0a, 526); put16(m, 0x0c, 994); put16(m, 0x0e, 526);
  put16(m, 0x10, 526); put16(m, 0x12, 526); put16(m, 0x14, 526);
  m[0x16] = 1; m[0x17] = 1;
  put16(m, 0x22, 994);
  return m;
}
function mirrorSmall() {
  const m = mirrorOpen();
  m[1] = 2;
  put16(m, 0x0c, 997);
  put16(m, 0x22, 997);
  return m;
}
function mirrorExif6() {
  const m = mirrorSmall();
  m[5] = 2;
  put16(m, 0x14, 997);
  return m;
}
function mirrorC1() {
  const m = mirrorSmall();
  m[0x18] = 5;
  m[0x19] = 7;
  return m;
}
function mirrorSize() {
  const m = mirrorC1();
  m[8] = 4;
  return m;
}

